-- Verify FMI for one fan
SELECT interact_fan_pivot, gift_metrics->>'Gift_Val_Usd' as gift_val, sess_dur_min 
FROM interactions WHERE interact_fan_pivot = 'FAN26602';

-- Check how many fans have no events record (through membership)
SELECT COUNT(*) FROM fans f WHERE NOT EXISTS (
    SELECT 1 FROM membershipandspending m 
    JOIN eventsandclub e ON m.member_reg = e.events_member_pivot 
    WHERE m.member_fan_pivot = f.user_registry
);

