args.sql:
-- Count fans with peak FMI > 20
SELECT COUNT(DISTINCT interact_fan_pivot) FROM interactions 
WHERE (gift_metrics->>'Gift_Val_Usd')::numeric / NULLIF(sess_dur_min::numeric, 0) > 20;

SELECT COUNT(*) FROM (
    SELECT interact_fan_pivot, 
           AVG((gift_metrics->>'Gift_Val_Usd')::numeric / NULLIF(sess_dur_min::numeric, 0)) AS fmi
    FROM interactions
    GROUP BY interact_fan_pivot
) sub WHERE fmi > 20;
